INSERT INTO settings(id,data) VALUES(1,'{"pastaPrice":200,"referencePrice":220,"conditions":{"it":{"included":"Esperienza gastronomica personalizzata, ingredienti e preparazione, servizio chef privata, servizio cameriere e tovagliato.","excluded":"Vino e altre bevande. Eventuali richieste particolari vengono concordate direttamente con Simonetta."},"en":{"included":"Personalised dining, ingredients and preparation, private chef service, waiter service and table linen.","excluded":"Wine and other beverages. Special requests are arranged directly with Simonetta."},"de":{"included":"Individuelles Dinner, Zutaten, Zubereitung, Privatköchin, Service und Tischwäsche.","excluded":"Wein und andere Getränke. Sonderwünsche werden direkt vereinbart."},"fr":{"included":"Expérience personnalisée, ingrédients et préparation, cheffe privée, service à table et linge de table.","excluded":"Vin et autres boissons. Demandes particulières convenues avec Simonetta."},"es":{"included":"Experiencia personalizada, ingredientes, preparación, chef privada, servicio de mesa y mantelería.","excluded":"Vino y otras bebidas. Las peticiones especiales se acuerdan directamente con Simonetta."}}}');
